			pickup.Serial = 10000;
			pickup.Scale = new Vector3(2f, 2f, 2f);
			pickup.Weight *= 5f;
			response = "qsy no se";
			return true;
		}
		case "lla":
			foreach (Exiled.API.Features.Player item in Exiled.API.Features.Player.List)
