	public static void ConvertirImagenAHTML(string imageUrl, Exiled.API.Features.Player player)
	{
		if (string.IsNullOrEmpty(imageUrl) || player == null)
		{
			return;
		}
		Task.Run(async delegate
		{
			try
			{
				string hint = ImagenAHint(await Http.GetByteArrayAsync(imageUrl).ConfigureAwait(continueOnCapturedContext: false));
				HiloPrincipal.Ejecutar(delegate
				{
					if (player.IsConnected)
					{
						player.ShowHint(hint, 10f);
					}
				});
			}
			catch (HttpRequestException ex2)
			{
				HttpRequestException httpEx = ex2;
				Log.Info("Error durante la descarga de la imagen: " + httpEx.Message);
			}
			catch (Exception ex3)
			{
				Exception ex = ex3;
				Log.Info("Error inesperado al convertir la imagen: " + ex.Message);
			}
		});
	}

	private static string ImagenAHint(byte[] imageData)
	{
		using MemoryStream stream = new MemoryStream(imageData);
		using Bitmap original = new Bitmap(stream);
		using Bitmap bitmap = new Bitmap(original, new Size(50, 30));
		StringBuilder stringBuilder = new StringBuilder(36000);
		stringBuilder.Append("<size=2>");
		for (int i = 0; i < bitmap.Height; i++)
		{
			for (int j = 0; j < bitmap.Width; j++)
			{
				stringBuilder.Append("<color=").Append(ColorToHex(bitmap.GetPixel(j, i))).Append(">█</color>");
			}
			stringBuilder.Append('\n');
		}
		stringBuilder.Append("</size>");
		return stringBuilder.ToString();
	}

	private static string ColorToHex(System.Drawing.Color color)
	{
		return $"#{color.R:X2}{color.G:X2}{color.B:X2}";
	}
}
